	RemoveSubscription(context.Context, *RemoveSubscriptionRequest) (*InfoResponse, error)
	GetGitHubConnection(context.Context, *GetGitHubConnectionRequest) (*GitHubConnection, error)
	ConfigureGitHubApp(context.Context, *ConfigureGitHubAppRequest) (*GitHubConnection, error)
	ConnectGitHubPersonalToken(context.Context, *ConnectGitHubPersonalTokenRequest) (*GitHubConnection, error)
	ListRepositoryDiscovery(context.Context, *ListRepositoryDiscoveryRequest) (*RepositoryDiscovery, error)
	ScanRepositoryRoot(context.Context, *ScanRepositoryRootRequest) (*RepositoryDiscovery, error)
	BeginGitHubSignIn(context.Context, *BeginGitHubSignInRequest) (*GitHubSignIn, error)
	GetGitHubSignIn(context.Context, *GitHubSignInRequest) (*GitHubSignIn, error)
	CancelGitHubSignIn(context.Context, *GitHubSignInRequest) (*GitHubSignIn, error)
	DisconnectGitHub(context.Context, *GetGitHubConnectionRequest) (*GitHubConnection, error)
	ListGitHubInstallations(context.Context, *ListGitHubInstallationsRequest) (*ListGitHubInstallationsResponse, error)
	ListGitHubRepositories(context.Context, *ListGitHubRepositoriesRequest) (*ListGitHubRepositoriesResponse, error)
	ImportGitHubRepository(context.Context, *ImportGitHubRepositoryRequest) (*ImportGitHubRepositoryResponse, error)
